inline ::flatbuffers::Offset<TCT> CreateTCT(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> STORM_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> STORM_NAME = 0,
    tctBasin BASIN = tctBasin::Unspecified,
    tctTrackKind TRACK_KIND = tctTrackKind::Forecast,
    tctTrackOrigin TRACK_ORIGIN = tctTrackOrigin::ExistingSystem,
    wxfModelClass MODEL_CLASS = wxfModelClass::Unspecified,
    ::flatbuffers::Offset<::flatbuffers::String> MODEL_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> MODEL_VERSION = 0,
    uint64_t INIT_TIME_MS = 0,
    wxfMemberKind MEMBER_KIND = wxfMemberKind::Member,
    uint16_t MEMBER_INDEX = 0,
    uint16_t ENSEMBLE_SIZE = 0,
    uint16_t WIND_AVERAGING_PERIOD_S = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<TCTPoint>>> POINTS = 0,
    ::flatbuffers::Offset<::flatbuffers::String> ORIGIN_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> DATASET_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> SOURCE_URL = 0,
    uint64_t RETRIEVED_AT = 0,
    wxfLicenseClass LICENSE_CLASS = wxfLicenseClass::RealTimeExperimental,
    ::flatbuffers::Offset<::flatbuffers::String> LICENSE_URL = 0,
    ::flatbuffers::Offset<::flatbuffers::String> CITATION = 0,
    ::flatbuffers::Offset<::flatbuffers::String> PRODUCER_PEER_ID = 0) {
  TCTBuilder builder_(_fbb);
  builder_.add_RETRIEVED_AT(RETRIEVED_AT);
  builder_.add_INIT_TIME_MS(INIT_TIME_MS);
  builder_.add_PRODUCER_PEER_ID(PRODUCER_PEER_ID);
  builder_.add_CITATION(CITATION);
  builder_.add_LICENSE_URL(LICENSE_URL);
  builder_.add_SOURCE_URL(SOURCE_URL);
  builder_.add_DATASET_ID(DATASET_ID);
  builder_.add_ORIGIN_ID(ORIGIN_ID);
  builder_.add_POINTS(POINTS);
  builder_.add_MODEL_VERSION(MODEL_VERSION);
  builder_.add_MODEL_ID(MODEL_ID);
  builder_.add_STORM_NAME(STORM_NAME);
  builder_.add_STORM_ID(STORM_ID);
  builder_.add_WIND_AVERAGING_PERIOD_S(WIND_AVERAGING_PERIOD_S);
  builder_.add_ENSEMBLE_SIZE(ENSEMBLE_SIZE);
  builder_.add_MEMBER_INDEX(MEMBER_INDEX);
  builder_.add_LICENSE_CLASS(LICENSE_CLASS);
  builder_.add_MEMBER_KIND(MEMBER_KIND);
  builder_.add_MODEL_CLASS(MODEL_CLASS);
  builder_.add_TRACK_ORIGIN(TRACK_ORIGIN);
  builder_.add_TRACK_KIND(TRACK_KIND);
  builder_.add_BASIN(BASIN);
  return builder_.Finish();
}

