inline const TCT *GetTCT(const void *buf) {
  return ::flatbuffers::GetRoot<TCT>(buf);
}

inline const TCT *GetSizePrefixedTCT(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<TCT>(buf);
}

inline const char *TCTIdentifier() {
  return "$TCT";
}

inline bool TCTBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, TCTIdentifier());
}

inline bool SizePrefixedTCTBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, TCTIdentifier(), true);
}

template <bool B = false>
inline bool VerifyTCTBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<TCT>(TCTIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedTCTBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<TCT>(TCTIdentifier());
}

inline void FinishTCTBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<TCT> root) {
  fbb.Finish(root, TCTIdentifier());
}

inline void FinishSizePrefixedTCTBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<TCT> root) {
  fbb.FinishSizePrefixed(root, TCTIdentifier());
}

inline std::unique_ptr<TCTT> UnPackTCT(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<TCTT>(GetTCT(buf)->UnPack(res));
}

inline std::unique_ptr<TCTT> UnPackSizePrefixedTCT(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<TCTT>(GetSizePrefixedTCT(buf)->UnPack(res));
}

